    public static final String AZURE_RESPONSE_TIMEOUT = "azure-response-timeout";
    public static final int CLIENT_TIMEOUT_BUFFER = 5;

    private static final ClientLogger LOGGER = new ClientLogger(LogsQueryHelper.class);
